import{_ as a,c as s,o as n,a2 as t}from"./chunks/framework.DkPtUiZm.js";const u=JSON.parse('{"title":"Prompts de génération du carrousel Google Play","description":"","frontmatter":{},"headers":[],"relativePath":"assets/google-play/sources/carrousel-v2/prompts.md","filePath":"assets/google-play/sources/carrousel-v2/prompts.md","lastUpdated":1795438092000}'),o={name:"assets/google-play/sources/carrousel-v2/prompts.md"};function r(i,e,l,p,c,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="prompts-de-generation-du-carrousel-google-play" tabindex="-1">Prompts de génération du carrousel Google Play <a class="header-anchor" href="#prompts-de-generation-du-carrousel-google-play" aria-label="Permalink to &quot;Prompts de génération du carrousel Google Play&quot;">​</a></h1><p>Les images sont des compositions marketing générées avec imagegen. Les PNG Android de référence restent disponibles dans <code>../captures/</code>. Les originaux générés sont conservés à côté des panoramas normalisés ; les exports téléphone sont les moitiés exactes de ces panoramas.</p><h2 id="panorama-1" tabindex="-1">Panorama 1 <a class="header-anchor" href="#panorama-1" aria-label="Permalink to &quot;Panorama 1&quot;">​</a></h2><p>Mode : outil imagegen intégré, composition marketing à partir des captures Android et du signe SIA ; ce premier panorama sert de référence de style aux suivants.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a polished Google Play screenshot marketing PANORAMA for SIA UI Demo. Output one seamless 2160 x 1920 px image, intended to be cut vertically at x=1080 into two consecutive 1080x1920 portrait slides. This is a premium editorial app-store campaign, not a flat screenshot sheet.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>References: image 1 is the REAL light catalogue app screen, image 2 is the REAL dark catalogue screen, image 3 is the exact SIA brand mark. Use screen images faithfully as photographic inserts inside realistic, unbranded Android smartphone mockups. Keep the UI, French labels, colors and controls of each supplied screen intact. Do not invent app functions, personal data or alternative screen designs. Keep the mark unchanged.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Art direction: sophisticated warm ice-white #F4FAFA background, deep ink #102335 typography, vivid teal #28D7C9 and electric blue #278CF0. Large bold modern sans-serif typography, generous breathing room, convincing matte metallic phone edges, tasteful soft studio shadows, subtle dimensional rounded modular shapes. Expensive, clean, visually exciting. Not childish, no excessive glossy 3D logo. No Apple/Samsung/Google Play logos, no download CTA, awards, badges or ratings.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Composition and continuity: a LARGE elegant phone showing the light catalogue sits in the lower center, slightly rotated in the picture plane, spanning the vertical center seam: its body and screen cross x=1080 so the right edge of slide 1 visibly continues as the SAME phone on slide 2. A second smaller phone showing the dark catalogue is on the right half, fully recognizable. A broad sculptural teal ribbon and small blue modular accents flow smoothly behind the phones across the seam. No divider line or visible gutter at x=1080. Phones must dominate the lower ~75% of the design while both slide headers remain clear. Treat each half as an attractive store screenshot AND the whole as one connected composition. Do not put headline text across the seam. Do not draw an extra phone at the seam.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exact French text, outside the phone screens:</span></span>
<span class="line"><span>LEFT HALF top small brand: &quot;SIA UI Demo&quot;</span></span>
<span class="line"><span>LEFT HALF headline, large, over two lines: &quot;Tous les&quot; / &quot;composants.&quot;</span></span>
<span class="line"><span>LEFT HALF smaller subheading: &quot;Un catalogue interactif, à portée de main.&quot;</span></span>
<span class="line"><span>RIGHT HALF headline, large, over two lines: &quot;Clair ou sombre.&quot; / &quot;Toujours cohérent.&quot;</span></span>
<span class="line"><span>RIGHT HALF smaller subheading: &quot;Les mêmes composants. Deux ambiances.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Typography must have perfect French accents and spelling. Avoid extra text. Keep important text at least 80 px away from each half&#39;s outer edges. Preserve the actual screenshots, without changing their UI text. Render high resolution for finished store artwork, with no watermark.</span></span></code></pre></div><h2 id="panorama-2" tabindex="-1">Panorama 2 <a class="header-anchor" href="#panorama-2" aria-label="Permalink to &quot;Panorama 2&quot;">​</a></h2><p>Mode : outil imagegen intégré, composition marketing à partir des captures Android et du panorama 1 comme référence de style.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create one finished Google Play marketing PANORAMA for SIA UI Demo, 2160x1920 px, split-ready at the vertical center x=1080 into TWO consecutive 1080x1920 store screenshots. Image 1 is a STYLE REFERENCE: match its premium unbranded Android phones, beautifully controlled studio shadows, bold editorial sans-serif typography, sculptural teal ribbon and blue modular pieces, SIA colors and clean depth. Do not reuse the catalogue UI or headlines from image 1. Images 2 and 3 are the ACTUAL APPLICATION SCREENS to insert faithfully inside the phones, not loose inspirations: preserve French UI content, controls, data, and theme colors. No invented features or redesigned app interface.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MANDATORY CONTINUITY: put the PRIMARY LARGE PHONE CENTER exactly on the panorama center line x=1080 so about half its body is visible on the LEFT slide and half continues on the RIGHT slide. Its entire body must look like ONE phone shared across the two halves, not two overlapping phones. A second smaller phone may stand farther right. The shared ribbon and modular background also cross the seam without a divider or gutter. Keep text separate and readable within each half (80px margins); no text crossing the seam. Large phones dominate the lower 70-75%. Strong readable copy and app-screen inserts. Keep important screen content recognizable. Some large phone crop across the center is intentional. Tasteful 3D matte metallic hardware, no brand logos on the phones, no hands, no download badges, prices, rankings, app ratings or watermark. Use only the exact French promotional copy given below, plus the reference screenshots&#39; text. Make this a convincing professional app-store campaign, not a documentation sheet.</span></span>
<span class="line"><span>PAIR 2 — FORMS AND KEYBOARD. Use a deep midnight navy #102335 background with teal #28D7C9 and electric blue #278CF0 ribbon highlights, white large type, subtle cool studio lighting. Primary central phone uses image 2 (real LIGHT structured form). Smaller right phone uses image 3 (real DARK form with actual Android keyboard visibly open). Keep the two themes as in the supplied screenshots.</span></span>
<span class="line"><span>LEFT HALF: small brand &quot;SIA UI Demo&quot;; headline over two lines &quot;Des formulaires&quot; / &quot;bien structurés.&quot;; subtitle &quot;Des champs clairs, des sections lisibles.&quot;</span></span>
<span class="line"><span>RIGHT HALF: headline over two lines &quot;Une saisie&quot; / &quot;qui reste fluide.&quot;; subtitle &quot;Le clavier garde toute sa place.&quot;</span></span>
<span class="line"><span>Perfect French spelling and accents. No extra marketing text.</span></span></code></pre></div><h2 id="panorama-3" tabindex="-1">Panorama 3 <a class="header-anchor" href="#panorama-3" aria-label="Permalink to &quot;Panorama 3&quot;">​</a></h2><p>Mode : outil imagegen intégré, composition marketing à partir des captures Android et du panorama 1 comme référence de style.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create one finished Google Play marketing PANORAMA for SIA UI Demo, 2160x1920 px, split-ready at the vertical center x=1080 into TWO consecutive 1080x1920 store screenshots. Image 1 is a STYLE REFERENCE: match its premium unbranded Android phones, beautifully controlled studio shadows, bold editorial sans-serif typography, sculptural teal ribbon and blue modular pieces, SIA colors and clean depth. Do not reuse the catalogue UI or headlines from image 1. Images 2 and 3 are the ACTUAL APPLICATION SCREENS to insert faithfully inside the phones, not loose inspirations: preserve French UI content, controls, data, and theme colors. No invented features or redesigned app interface.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MANDATORY CONTINUITY: put the PRIMARY LARGE PHONE CENTER exactly on the panorama center line x=1080 so about half its body is visible on the LEFT slide and half continues on the RIGHT slide. Its entire body must look like ONE phone shared across the two halves, not two overlapping phones. A second smaller phone may stand farther right. The shared ribbon and modular background also cross the seam without a divider or gutter. Keep text separate and readable within each half (80px margins); no text crossing the seam. Large phones dominate the lower 70-75%. Strong readable copy and app-screen inserts. Keep important screen content recognizable. Some large phone crop across the center is intentional. Tasteful 3D matte metallic hardware, no brand logos on the phones, no hands, no download badges, prices, rankings, app ratings or watermark. Use only the exact French promotional copy given below, plus the reference screenshots&#39; text. Make this a convincing professional app-store campaign, not a documentation sheet.</span></span>
<span class="line"><span>PAIR 3 — BOTTOM SHEET AND CALENDAR. Use an ice-white #F4FAFA background with very pale aqua gradients, ink #102335 headings, teal and blue sweeping sculptural ribbon. Primary central phone uses image 2 with the real LIGHT bottom sheet OPEN, its handle, search field, resources and footer must remain visible. The smaller right phone shows image 3, the DARK calendar for November 2026. Preserve source layouts and content.</span></span>
<span class="line"><span>LEFT HALF: small brand &quot;SIA UI Demo&quot;; headline over two lines &quot;Feuilles souples.&quot; / &quot;Gestes naturels.&quot;; subtitle &quot;Ouvrir, glisser, sélectionner.&quot;</span></span>
<span class="line"><span>RIGHT HALF: headline over two lines &quot;Les dates,&quot; / &quot;sans détour.&quot;; subtitle &quot;Calendrier et réservation locale.&quot;</span></span>
<span class="line"><span>Perfect French spelling and accents. No extra marketing text.</span></span></code></pre></div><h2 id="panorama-4" tabindex="-1">Panorama 4 <a class="header-anchor" href="#panorama-4" aria-label="Permalink to &quot;Panorama 4&quot;">​</a></h2><p>Mode : outil imagegen intégré, composition marketing à partir des captures Android et du panorama 1 comme référence de style.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create one finished Google Play marketing PANORAMA for SIA UI Demo, 2160x1920 px, split-ready at the vertical center x=1080 into TWO consecutive 1080x1920 store screenshots. Image 1 is a STYLE REFERENCE: match its premium unbranded Android phones, beautifully controlled studio shadows, bold editorial sans-serif typography, sculptural teal ribbon and blue modular pieces, SIA colors and clean depth. Do not reuse the catalogue UI or headlines from image 1. Images 2 and 3 are the ACTUAL APPLICATION SCREENS to insert faithfully inside the phones, not loose inspirations: preserve French UI content, controls, data, and theme colors. No invented features or redesigned app interface.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MANDATORY CONTINUITY: put the PRIMARY LARGE PHONE CENTER exactly on the panorama center line x=1080 so about half its body is visible on the LEFT slide and half continues on the RIGHT slide. Its entire body must look like ONE phone shared across the two halves, not two overlapping phones. A second smaller phone may stand farther right. The shared ribbon and modular background also cross the seam without a divider or gutter. Keep text separate and readable within each half (80px margins); no text crossing the seam. Large phones dominate the lower 70-75%. Strong readable copy and app-screen inserts. Keep important screen content recognizable. Some large phone crop across the center is intentional. Tasteful 3D matte metallic hardware, no brand logos on the phones, no hands, no download badges, prices, rankings, app ratings or watermark. Use only the exact French promotional copy given below, plus the reference screenshots&#39; text. Make this a convincing professional app-store campaign, not a documentation sheet.</span></span>
<span class="line"><span>PAIR 4 — LOCAL CONTACT DEMO. Use a midnight navy #102335 background with restrained electric blue light and a continuous teal ribbon, white bold headlines and cool studio phone lighting. Primary central phone uses image 2 (real LIGHT contacts list); smaller right phone uses image 3 (real DARK contacts list). Preserve the fictitious Amélie Bernard / Amina Njoya / example.test records, statuses and actions. This is a LOCAL DEMO, no claim of cloud sync, online collaboration or production CRM.</span></span>
<span class="line"><span>LEFT HALF: small brand &quot;SIA UI Demo&quot;; headline over two lines &quot;Des contacts.&quot; / &quot;Un vrai parcours.&quot;; subtitle &quot;Listes, statuts et actions locales.&quot;</span></span>
<span class="line"><span>RIGHT HALF: headline over two lines &quot;Local, simple&quot; / &quot;et interactif.&quot;; subtitle &quot;Des données fictives pour tout explorer.&quot;</span></span>
<span class="line"><span>Perfect French spelling and accents. No extra marketing text.</span></span></code></pre></div>`,14)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
